{{ config(order_by='(fs_category, fs_caption, fs_line, source_system)') }}

-- Match rules from the lower-cased income-statement labels to a report line of dim_pl_report_line. '' in source_system,
-- fs_caption or fs_line matches anything; the most specific matching rule wins (hnh_pl_report_line_pick).
select
    source_system, fs_category, fs_caption, fs_line, pl_line_code,
    toUInt8((source_system != '') + 2 * (fs_caption != '') + 4 * (fs_line != '')) as score
from values('source_system String, fs_category String, fs_caption String, fs_line String, pl_line_code String',
